content.content:
# A steward flags a person with a reason until a date: while the sheet's today is on or before it,
# only a steward may open a claim of theirs.
validate:
  class: net.officefloor.hq.app.person.ValidateFlag
  next: flag
flag:
  class: net.officefloor.hq.app.person.FlagPerson
  govern: [ transaction ]
  next: record
# Audit only once the flag is saved.
record:
  class: net.officefloor.hq.app.person.RecordPersonFlagged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
=== FlagRequest
package net.officefloor.hq.app.person;

/** Body of a flag, as typed: its reason, the date it is in force until (inclusive) and who makes the change. */
public record FlagRequest(String reason, String until, String user) {
}
=== ValidateFlag
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Only a steward may flag a person, and only with a reason and an until-date. */
public class ValidateFlag {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody FlagRequest request, Settings settings,
            Out<FlagChange> body, Out<Actor> actor) throws InvalidSheetRequestException {
        String user = request != null ? request.user() : null;
        if (user == null || settings.role(sheetId, user) != Role.STEWARD) {
            throw new InvalidSheetRequestException("Only a steward can flag a person");
        }
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (reason.isEmpty()) throw new InvalidSheetRequestException("A flag needs a reason");
        String raw = request.until() == null ? "" : request.until().trim();
        LocalDate until;
        try {
            until = LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
        }
        body.set(new FlagChange(reason, until, user));
        actor.set(new Actor(user));
    }
}
=== FlagPerson
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Flags the person, replacing any flag they had. Not an edit: the person's version is untouched. */
public class FlagPerson {
    public void flag(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            @Val FlagChange change, People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = people.lock(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        person.setFlag(change.reason(), change.until());
        people.saveFlag(person);
        personOut.set(person);
    }
}
=== FlagChange
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated flag: its reason (trimmed, never blank), its until-date and who makes the change. */
public record FlagChange(String reason, LocalDate until, String user) {
}
=== RecordPersonFlagged
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Val;

/** Runs after the flag is saved: PERSON_FLAGGED with its reason and until-date. */
public class RecordPersonFlagged {
    public void record(@Val Person person, @Val Actor actor, Audit audit) {
        audit.record("PERSON_FLAGGED sheet=" + person.getSheetId() + " by=" + actor.user() + " name=" + person.getName()
                + " reason=" + person.getFlagReason() + " until=" + person.getFlagUntil());
    }
}
=== Person
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet. `id` is null until the person is first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    /** The person's grades by the date each is in force from; LocalDate.MIN for the first one,
     *  which applies from the beginning of time. */
    private TreeMap<LocalDate, String> grades = new TreeMap<>();
    /** The sheet's today as it was when the person was read (null: the person is new). */
    private LocalDate today;
    /** A grade this save records, from its date (null: the save records none). */
    private DatedGrade newGrade;
    private int version;
    /** The person's own terms in days from the beginning of time (null: none). */
    private Integer terms;
    /** The person's own terms by the date each is in force from (a null value: none from then). */
    private TreeMap<LocalDate, Integer> datedTerms = new TreeMap<>();
    /** Whether this save changes the person's own terms. */
    private boolean termsChanged;
    /** The person's contact (null: none). */
    private String contact;
    /** Whether this save changes the person's contact. */
    private boolean contactChanged;
