import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
  tags: string[];
  /** Snapshot lines, oldest first: `<day left> <due-total>` (n/a when it was n/a). */
  snapshots: string[];
  /** Statements still standing, oldest first: `<statement date> <due-total>` (n/a when it was n/a). */
  statementLines: string[];
  /** The reason of the person's flag while it is in force (the sheet's today on or before its
   *  until-date), null when none is; only a steward may open their claims then. */
  flag: string | null;
};

/** Whether the sheet's `today` (yyyy-mm-dd) has reached the person's retirement date. */
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}

